function gainPreview(){return 10+game.boosts.discipline*4}
function train(key){const c=game.career;if(!c)return;const mapping={speed:['speed','acceleration'],stamina:['stamina','strength'],dribbling:['dribbling','control'],passing:['shortPass','longPass','vision'],finishing:['finishing','shotPower'],setpieces:['freeKick','penalties'],heading:['heading','positioning'],defending:['tackling','marking','positioning'],reflexes:['reflexes','positioning']};const xp=10+game.boosts.discipline*4;c.experience+=xp;c.trainingCount=(c.trainingCount||0)+1;let gains=0;for(const attr of mapping[key]||[]){const old=c.attrs[attr];const growthFactor=1+game.boosts.genetics*.18;const chance=old<65?1:old<82?.75:old<95?.45:.2;if(Math.random()<chance){c.attrs[attr]=Math.min(100,old+Math.max(1,Math.floor(growthFactor)));if(c.attrs[attr]>old)gains++}}c.careerStats.bestRating=Math.max(c.careerStats.bestRating,avg(c.attrs));save();render();notify(`Sesión completada · +${xp} XP · ${gains?`+${gains} mejora${gains>1?'s':''}`:'experiencia ganada'}`)}
