iv></div><div class="grid grid-2"><div class="card"><div class="row"><span class="muted small">Goles por partido</span><b>${c.careerStats.apps?(c.careerStats.goals/c.careerStats.apps).toFixed(2):'0.00'}</b></div><div class="divider"></div><div class="row"><span class="muted small">Asistencias por partido</span><b>${c.careerStats.apps?(c.careerStats.assists/c.careerStats.apps).toFixed(2):'0.00'}</b></div></div><div class="card"><div class="row"><span class="muted small">Títulos colectivos</span><b>${c.careerStats.titles.length}</b></div><div class="divider"></div><div class="row"><span class="muted small">Premios individuales</span><b>${c.careerStats.awards.length}</b></div></div></div>`}
