function legacyView(){const c=game.career;return `<div class="hero" style="min-height:170px"><div class="hero-copy"><div class="eyebrow">EL LEGADO TRASCIENDE GENERACIONES</div><h2 style="font-size:26px;margin-top:7px">Una leyenda nunca<br>juega sola.</h2><p>Tu trayectoria se convierte en puntos de legado. Invierte en mejoras permanentes y cada nuevo futbolista heredará parte de tu grandeza.</p></div><div style="position:relative;z-index:1;margin-left:auto;text-align:center;padding:0 28px"><div style="font:700 40px var(--display);color:var(--lime)">${game.legacyPoints}</div><div class="eyebrow">PUNTOS LP</div></div></div><div class="section-head"><div><h2 class="section-title">Mejoras permanentes</h2><div class="section-note">Se acumulan y aplican en todas tus futuras carreras.</div></div><span class="tag lime">GENERACIÓN ${game.generation}</span></div><div class="grid grid-3">${BOOSTS.map(([id,name,desc,price])=>{const level=game.boosts[id]||0,cost=price*(level+1);return `<div class="card boost-card"><div class="row"><div class="train-icon">${({talent:'✦',genetics:'⌁',discipline:'◈',stamina:'♧',winner:'♜',prodigy:'☄'})[id]}</div><span class="tag">Nv. ${level}</span></div><h3>${name}</h3><p>${desc}</p><div class="boost-level">${Array.from({length:5},(_,i)=>`<i class="${i<Math.min(level,5)?'on':''}"></i>`).join('')}</div><div class="row"><span class="boost-price">${cost} LP · ${level>=5?'Nivel máximo':'Siguiente nivel'}</span><button class="btn ${game.legacyPoints>=cost&&level<5?'btn-primary':'btn-secondary'}" ${game.legacyPoints<cost||level>=5?'disabled':''} onclick="buyBoost('${id}')">${level>=5?'Máximo':'Mejorar'}</button></div></div>`}).join('')}</div><div class="section-head"><div><h2 class="section-title">Historial de leyendas</h2><div class="section-note">Todas las generaciones se conservan permanentemente en este dispositivo.</div></div>${c?`<button class="btn btn-danger" onclick="retireCareer('voluntary')">Retirar futbolista</button>`:''}</div>${game.history.length?`<div class="stack">${[...game.history].reverse().map(h=>`<div class="card"><div class="row"><div class="player-data"><h3>${esc(h.name)}</h3><p>${esc(h.nationality)} · ${h.debutAge}–${h.retirementAge} años · ${h.seasons} temporadas</p></div><span class="tag lime">${h.legacyPoints} LP</span></div><div class="grid grid-4" style="margin-top:15px"><div><div class="muted small">CLUBES</div><b class="small">${h.clubs.map(esc).join(' · ')}</b></div><div><div class="muted small">PARTIDOS</div><b>${h.apps}</b></div><div><div class="muted small">G / AS</div><b>${h.goals} / ${h.assists}</b></div><div><div class="muted small">TÍTULOS · PREMIOS</div><b>${h.titles.length} · ${h.awards.length}</b></div></div><div class="footer-hint">Valoración máxima ${h.bestRating} · Retiro: ${esc(h.reason)}</div></div>`).join('')}</div>`:'<div class="card empty"><div class="empty-icon">✦</div>Aún no hay generaciones retiradas.<br>Completa tu carrera y aquí aparecerán tus leyendas.</div>'}<div class="section-head"><div><h2 class="section-title">Generación actual</h2><div class="section-note">El capítulo que está escribiéndose.</div></div></div><div class="card row"><div><b>${c?`${esc(c.name)} · ${c.age} años`: 'Sin carrera activa'}</b><div class="small muted" style="margin-top:4px">${c?`${esc(c.club)} · Temporada ${c.season} de 20`:'Crea un futbolista para comenzar una nueva generación.'}</div></div>${c?'<span class="tag lime">ACTIVA</span>':`<button class="btn btn-primary" onclick="go('player')">Crear futbolista</button>`}</div>`}
