ión consolidada.</div>`}
 function generateOffers(c){let candidates=CLUBS.filter(x=>x.name!==c.club&&x.level<=Math.min(5,Math.floor((attrOverall()-30)/9)+1));if(c.season>=3&&attrOverall()>59)candidates=CLUBS.filter(x=>x.name!==c.club&&x.level<=Math.min(5,Math.floor((attrOverall()-25)/9)+1));return candidates.sort((a,b)=>a.level-b.level).slice(-3).map(x=>({...x,salary:Math.max(c.salary+2,Math.round((x.level*8+attrOverall()*.6)*(1+c.season*.06)))}))}
