 function homeView(c){if(!c)return emptyCareer();const o=attrOverall(),next=c.matchesPlayed<3?`Próximo partido · Jornada ${c.matchesPlayed+1}`:'Temporada completada';const upcoming=c.matchesPlayed<3?c.schedule[c.matchesPlayed]:null;return `<div class="hero"><div class="hero-copy"><div class="eyebrow">${esc(c.club)} · ${esc(c.league)}</div><h2>Tu leyenda está<br>en construcción, ${esc(c.name.split(' ')[0])}.</h2><p>${c.age} años · ${esc(c.positionName)} · ${esc(c.nationality)}. Una carrera entera por delante. El próximo capítulo empieza en el campo.</p><button class="btn btn-primary" onclick="go('calendar')">${upcoming?'Preparar partido':'Ver temporada'} <span>→</span></button></div></div><div class="section-head"><div><h2 class="section-title">Panel de temporada</h2><div class="section-note">Tu progreso, de un vistazo.</div></div><span class="tag lime">● EN CARRERA</span></div><div class="grid grid-4">${statCard('VALORACIÓN',o,'Media de atributos','✦')}${statCard('PARTIDOS',c.seasonStats.apps,`${c.matchesPlayed}/3 jornadas disputadas`,'◷')}${statCard('GOLES',c.seasonStats.goals,'Esta temporada','◎')}${statCard('SALARIO',`€${c.salary}k`,'por temporada','↗')}</div><div class="section-head"><div><h2 class="section-title">Tu futbolista</h2><div class="section-note">Condiciones perfectas para rendir.</div></div><button class="btn btn-quiet" onclick="go('player')">Ver perfil →</button></div><div class="grid grid-2"><div class="card player-card"><div class="player-portrait">${posEmoji(c.position)}</div><div class="player-data"><h3>${esc(c.name)}</h3><p>${esc(c.club)} · ${c.age} años</p><div style="display:flex;gap:6px;margin-top:9px"><span class="tag lime">${c.position}</span><span class="tag">${esc(c.nationality)}</span></div></div><div class="player-rating"><div class="rating-num">${o}</div><div class="rating-label">MEDIA</div></div></div><div class="card"><div class="row"><b style="font:600 13px var(--display)">Estado de ánimo</b><span class="tag lime">100% · PERFECTO</span></div><div class="divider"></div><div class="row small"><span class="muted">Energía</span><b>100%</b></div><div class="bar green-bar" style="margin:7px 0 12px"><i style="width:100%"></i></div><div class="row small"><span class="muted">Actitud y motivación</span><b>100%</b></div><div class="bar" style="margin-top:7px"><i style="width:100%"></i></div></div></div><div class="section-head"><div><h2 class="section-title">Próximo encuentro</h2><div class="section-note">La temporada se juega partido a partido.</div></div><button class="btn btn-quiet" onclick="go('calendar')">Calendario →</button></div>${upcoming?matchPreview(upcoming,c):`<div class="notice">Has completado las tres jornadas. <button class="btn btn-secondary" onclick="finishSeason()" style="margin-left:8px">Cerrar temporada</button></div>`}`}
